-- College Scheduler - Full Demonstration Database (v10 - Complete Integrated Dataset)
-- Generated from the verified functional v5 dataset while preserving schema, insertion order and relationships.
-- Dataset size: 150 students, 30 lecturers, 2 campuses, 6 buildings, 30 rooms, 5 departments, 15 programs, 30 cohorts, 50 modules and 600 timetable events.
-- Coverage: 3 programs per department, 2 cohorts per program, 5 students per cohort, 5 rooms per building, curriculum and timetable data for every cohort.
-- Uniqueness: all student and lecturer full names, emails and account numbers are unique. Names supplied by the project owner.
-- Shared demo password for all generated accounts: Password123!
-- Run against a clean migrated database. Existing migration-seeded lookup rows are preserved.
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF EXISTS (SELECT 1 FROM [dbo].[Campuses])
   OR EXISTS (SELECT 1 FROM [dbo].[Departments])
   OR EXISTS (SELECT 1 FROM [dbo].[TimetableEvents])
   OR EXISTS (SELECT 1 FROM [dbo].[AspNetUsers])
    THROW 51000, 'Demo data was not inserted because the database already contains application or Identity users. Use a clean migrated database.', 1;
GO
BEGIN TRANSACTION;
GO

-- Migrations may seed lookup rows. On a clean database there are no dependent
-- application records yet, so replace those rows with the deterministic IDs
-- used throughout this demonstration dataset.
DELETE FROM [dbo].[AspNetUserRoles];
DELETE FROM [dbo].[AspNetRoles];
DELETE FROM [dbo].[Terms];
DELETE FROM [dbo].[AcademicYears];
DELETE FROM [dbo].[NotificationTypes];
DELETE FROM [dbo].[RequestStatuses];
DELETE FROM [dbo].[RequestTypes];
DELETE FROM [dbo].[EventStatuses];
DELETE FROM [dbo].[UnavailabilityReasonTypes];
DELETE FROM [dbo].[Features];
DELETE FROM [dbo].[RoomTypes];
DBCC CHECKIDENT ('[dbo].[Terms]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[AcademicYears]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[NotificationTypes]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[RequestStatuses]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[RequestTypes]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[EventStatuses]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[UnavailabilityReasonTypes]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[Features]', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('[dbo].[RoomTypes]', RESEED, 0) WITH NO_INFOMSGS;
GO
